const parseComponent = require('./parser')
const createHelpers = require('./helpers')
const parseRequest = require('./utils/parse-request')
const { matchCondition } = require('./utils/match-condition')
const addQuery = require('./utils/add-query')
const async = require('async')
const normalize = require('./utils/normalize')
const getEntryName = require('./utils/get-entry-name')
const AppEntryDependency = require('./dependencies/AppEntryDependency')
const RecordResourceMapDependency = require('./dependencies/RecordResourceMapDependency')
const CommonJsVariableDependency = require('./dependencies/CommonJsVariableDependency')
const DynamicEntryDependency = require('./dependencies/DynamicEntryDependency')
const RecordModuleIdMapDependency = require('./dependencies/RecordModuleIdMapDependency')
const tsWatchRunLoaderFilter = require('./utils/ts-loader-watch-run-loader-filter')
const { isReact } = require('./utils/env')
const preProcessJson = require('./utils/pre-process-json')
const path = require('path')
const processWeb = require('./web')
const processReact = require('./react')
const genMpxCustomElement = require('./runtime-render/gen-mpx-custom-element')

/**
 * @this {MpxLoaderContext<any>}
 * @param {string} content
 */
module.exports = function (content) {
  this.cacheable()

  // 兼容处理处理ts-loader中watch-run/updateFile逻辑，直接跳过当前loader及后续的loader返回内容
  const pathExtname = path.extname(this.resourcePath)
  if (!['.vue', '.mpx'].includes(pathExtname)) {
    this.loaderIndex = tsWatchRunLoaderFilter(this.loaders, this.loaderIndex)
    return content
  }

  const mpx = this.getMpx()
  if (!mpx) {
    return content
  }
  const { resourcePath, queryObj } = parseRequest(this.resource)

  const packageRoot = queryObj.packageRoot || mpx.currentPackageRoot
  const packageName = packageRoot || 'main'
  const independent = queryObj.independent
  const pagesMap = mpx.pagesMap
  const componentsMap = mpx.componentsMap[packageName]
  const mode = mpx.mode
  const env = mpx.env
  const i18n = mpx.i18n
  const globalSrcMode = mpx.srcMode
  const localSrcMode = queryObj.mode
  const srcMode = localSrcMode || globalSrcMode
  const autoScope = matchCondition(resourcePath, mpx.autoScopeRules)
  const isRuntimeMode = queryObj.isDynamic

  const emitWarning = (msg, loc) => {
    this.emitWarning(
      new Error('[Mpx json warning][' + (loc || this.resourcePath) + ']: ' + msg)
    )
  }

  const emitError = (msg, loc) => {
    this.emitError(
      new Error('[Mpx json error][' + (loc || this.resourcePath) + ']: ' + msg)
    )
  }

  let ctorType = pagesMap[resourcePath]
    ? 'page'
    : componentsMap[resourcePath]
      ? 'component'
      : 'app'

  // 支持资源query传入isPage或isComponent支持页面/组件单独编译
  if (ctorType === 'app' && (queryObj.isComponent || queryObj.isPage)) {
    const entryName = getEntryName(this) || mpx.getOutputPath(resourcePath, queryObj.isComponent ? 'component' : 'page')
    ctorType = queryObj.isComponent ? 'component' : 'page'
    this._module.addPresentationalDependency(new RecordResourceMapDependency(resourcePath, ctorType, entryName, packageRoot))
  }

  if (ctorType === 'app') {
    const appName = getEntryName(this)
    if (appName) this._module.addPresentationalDependency(new AppEntryDependency(resourcePath, appName))
  }

  if (isRuntimeMode) {
    const { request, outputPath } = genMpxCustomElement(packageName)
    this._module.addPresentationalDependency(new DynamicEntryDependency([0, 0], request, 'component', outputPath, packageRoot, '', '', { replaceContent: '', postSubpackageEntry: true }))
  }

  const loaderContext = this
  const isProduction = this.minimize || process.env.NODE_ENV === 'production'
  const filePath = this.resourcePath
  const moduleId = mpx.getModuleId(resourcePath, ctorType === 'app')
  this._module.addPresentationalDependency(new RecordModuleIdMapDependency(moduleId, resourcePath))

  const parts = parseComponent(content, {
    filePath,
    needMap: this.sourceMap,
    mode,
    env
  })

  const {
    getRequire
  } = createHelpers(loaderContext)

  const callback = this.async()

  async.waterfall([
    (callback) => {
      preProcessJson({
        json: parts.json || {},
        srcMode,
        emitWarning,
        emitError,
        ctorType,
        resourcePath,
        loaderContext
      }, (err, jsonInfo) => {
        if (err) return callback(err)
        callback(null, jsonInfo)
      })
    },
    (jsonInfo, callback) => {
      const {
        componentPlaceholder,
        componentGenerics,
        usingComponentsInfo,
        originalUsingComponents,
        jsonContent
      } = jsonInfo
      const hasScoped = parts.styles.some(({ scoped }) => scoped) || autoScope
      const templateAttrs = parts.template && parts.template.attrs
      const hasComment = templateAttrs && templateAttrs.comments
      const isNative = false

      // 处理mode为web时输出vue格式文件
      if (mode === 'web') {
        return processWeb({
          parts,
          jsonContent,
          loaderContext,
          pagesMap,
          componentsMap,
          queryObj,
          ctorType,
          srcMode,
          moduleId,
          isProduction,
          hasScoped,
          hasComment,
          isNative,
          usingComponentsInfo,
          originalUsingComponents,
          componentGenerics,
          componentPlaceholder,
          autoScope,
          callback
        })
      }
      // 处理mode为react时输出js格式文件
      if (isReact(mode)) {
        return processReact({
          parts,
          jsonContent,
          loaderContext,
          pagesMap,
          componentsMap,
          queryObj,
          ctorType,
          srcMode,
          moduleId,
          isProduction,
          hasScoped,
          hasComment,
          isNative,
          usingComponentsInfo,
          originalUsingComponents,
          componentGenerics,
          componentPlaceholder,
          autoScope,
          callback
        })
      }

      const moduleGraph = this._compilation.moduleGraph

      const issuer = moduleGraph.getIssuer(this._module)

      if (issuer) {
        return callback(new Error(`Current ${ctorType} [${this.resourcePath}] is issued by [${issuer.resource}], which is not allowed!`))
      }

      let output = ''
      // 注入模块id及资源路径
      output += `global.currentModuleId = ${JSON.stringify(moduleId)}\n`
      if (!isProduction) {
        output += `global.currentResource = ${JSON.stringify(filePath)}\n`
      }

